/**
 * Rendering half of `pnpm docs:schemas`: turns normalized schemas into the Markdown tables and the
 * JSON bundle under `skills/ignifx/references/formats/`.
 */
import type { SchemaDoc, SchemaFieldDoc } from "./schema-source.ts";

/** Notice stamped into every generated file so a human editing it is warned. */
export const GENERATED_NOTICE = "<!-- Generated by `pnpm docs:schemas`. Do not edit by hand. -->";

/**
 * Escapes the pipe characters that would otherwise break a Markdown table cell.
 *
 * @param text - Raw cell text.
 * @returns Text safe to place inside a table cell.
 */
function cell(text: string): string {
  return text.replaceAll("|", "\\|").replaceAll("\n", " ").trim();
}

/**
 * Renders one `references/formats/<format>.md` page.
 *
 * @param format - The format group name.
 * @param schemas - The schemas that belong to it, sorted by type id.
 * @returns The full Markdown page.
 */
export function renderFormatPage(format: string, schemas: readonly SchemaDoc[]): string {
  const lines: string[] = [`# ${format}`, "", GENERATED_NOTICE, ""];
  for (const schema of schemas) {
    lines.push(`## ${schema.title} (\`${schema.typeId}\`)`, "");
    if (schema.description !== "") {
      lines.push(schema.description, "");
    }
    lines.push("| Field | Kind | Default | Description |", "|---|---|---|---|");
    for (const field of schema.fields) {
      pushFieldRows(lines, field.name, field);
    }
    lines.push("");
  }
  return `${lines.join("\n").trimEnd()}\n`;
}

/**
 * Appends a field's table row, then a row per sub-field of the record it is or holds: an
 * `optional` or `record` field's sub-fields read `name.sub`, an array item's `name[].sub`, a map
 * value's `name.*.sub`.
 *
 * @param lines - The page being built.
 * @param path - The field's path from the component, as the row names it.
 * @param field - The field.
 */
function pushFieldRows(lines: string[], path: string, field: SchemaFieldDoc): void {
  const defaultCell = field.defaultValue === null ? "—" : `\`${field.defaultValue}\``;
  const assetType = field.metadata["assetType"];
  const kind = typeof assetType === "string" ? `${field.kind} (${assetType})` : field.kind;
  lines.push(`| \`${cell(path)}\` | \`${cell(kind)}\` | ${defaultCell} | ${cell(field.description)} |`);
  for (const [prefix, holder] of nestedRecords(path, field)) {
    for (const sub of holder.nested.fields ?? []) {
      pushFieldRows(lines, `${prefix}.${sub.name}`, sub);
    }
  }
}

/**
 * The records a field is or holds, with the path prefix their sub-fields are named under.
 *
 * @param path - The field's path.
 * @param field - The field.
 * @returns Each record and its prefix.
 */
function nestedRecords(path: string, field: SchemaFieldDoc): [string, SchemaFieldDoc][] {
  if (field.nested.fields !== undefined) {
    return [[path, field]];
  }
  const { item, value, inner } = field.nested;
  if (inner !== undefined) {
    return nestedRecords(path, inner);
  }
  if (item !== undefined) {
    return nestedRecords(`${path}[]`, item);
  }
  if (value !== undefined) {
    return nestedRecords(`${path}.*`, value);
  }
  return [];
}

/**
 * The bundle's JSON for one field: its kind, default, description and metadata, then what its
 * composite kind holds, under the member names core's `SchemaFieldDescription` uses.
 *
 * @param field - The field.
 * @returns The JSON object.
 */
function bundleField(field: SchemaFieldDoc): Record<string, unknown> {
  const { item, fields, value, inner } = field.nested;
  return {
    kind: field.kind,
    default: field.defaultValue,
    description: field.description,
    ...field.metadata,
    ...(item === undefined ? {} : { item: bundleField(item) }),
    ...(fields === undefined ? {} : { fields: Object.fromEntries(fields.map((sub) => [sub.name, bundleField(sub)])) }),
    ...(value === undefined ? {} : { value: bundleField(value) }),
    ...(inner === undefined ? {} : { inner: bundleField(inner) }),
  };
}

/**
 * Renders the `ignifx.schemas.json` bundle.
 *
 * @param version - The current release version of the fixed version line.
 * @param schemas - Every schema in the workspace, sorted by type id.
 * @returns Pretty-printed JSON with a trailing newline.
 */
export function renderSchemaBundle(version: string, schemas: readonly SchemaDoc[]): string {
  const bundle = {
    generatedBy: "pnpm docs:schemas",
    ignifxVersion: version,
    schemas: Object.fromEntries(
      schemas.map((schema) => [
        schema.typeId,
        {
          title: schema.title,
          format: schema.format,
          description: schema.description,
          package: `packages/${schema.packageDirectory}`,
          fields: Object.fromEntries(schema.fields.map((field) => [field.name, bundleField(field)])),
        },
      ]),
    ),
  };
  return `${JSON.stringify(bundle, null, 2)}\n`;
}
